                module Action
                module StepTimedLinkedOverlay
                ; Документация [алгоритм и проверка](../../Docs/ActionTimedLinkedState.md)
                ; -----------------------------------------
                ; Уменьшение таймера, восстановление состояния и обновление связанного сегмента либо создание класса 17
                ; исходная запись 17, адреса F3C8..F3EF
                ; In:
                ;   HL, DE, BC и AF числовых аргументов не задают, входной Carry учитывается DEC таймера
                ;   IX указывает FActionRecord с PhaseMoveTimer, TimedResumeCode, Unknown11, LinkedIndex и входами общих помощников
                ;   действуют договоры PrepareLinkedRecordContext, NextRandomWord0, CheckAndToggleLinkedOverlay и CheckMissileSpawnWindow
                ;   ACTION банка 0, перенесённый код банка 5, таблицы и экранные буферы доступны, CPU-стек допускает рамки детей, IRQ исключены
                ;   читается Component0.High, для активной записи доступны остальные фазовые поля, класс, состояние и порог
                ;   OffsetScaleLow и OffsetScaleHigh активной записи доступны для записи, ACTION банка 0 и общая RAM доступны
                ;   действует договор ApplyObjectOffsetVector, шесть байтов под SP и внешний возврат не перекрывают его код, таблицы, операнды и результаты
                ;   IRQ и повторный вход исключены
                ;   для исходных числовых постусловий записи детей не должны менять исполняемый вычислитель, таблицы и внешний возврат
                ; Out:
                ;   PhaseMoveTimer уменьшается на один по модулю 256, исходный ноль становится FF и не вызывает истечение
                ;   только при исходном таймере 1 StateCode получает TimedResumeCode, затем управление сразу идёт к F0F8
                ;   при ненулевом новом таймере подготавливается связанный контекст, его Z пропускает оба следующих общих пути
                ;   при доступном контексте обновляется поток 0, его L сравнивается с полным Unknown11
                ;   при L>=Unknown11 выполняется общий CheckMissileSpawnWindow с исходными H и A=L
                ;   при L<Unknown11 вызывается полный CheckAndToggleLinkedOverlay, его Carry здесь игнорируется
                ;   на всех путях общий F0F8 исполняется один раз до внешнего RET, включая хвостовой переход через CheckMissileSpawnWindow
                ;   общий хвост использует итоговые фазы, масштабы, класс и состояние после достигнутых детей
                ;   при итоговом Component0.High=80 общий хвост возвращает AF=8042 и сохраняет остальные результаты детей, собственный таймер и изменения записи не откатываются, R добавляет четыре M1
                ;   на активной ветви нижеследующие результаты вычислителя относятся к V из прежнего OffsetScaleLow и выбранного старшего байта
                ;   HL=(-Q) AND FFFF при бите 7 S=1, иначе HL=Q, DE=Q при бите 7 S=1, иначе DE=abs(V)
                ;   BC - B=W[Offset0], C=0
                ;   AF - A=S, F от 16-разрядного 0-Q при бите 7 S=1, иначе флаги логического XOR с результатом S
                ;   HL', DE', BC' сохраняют результаты реально достигнутых детей
                ;   AF' - A'=U, F'=(U AND 28) OR (40 при U=0) OR (10 при 2*((P SHR 16) AND 0F)+(U AND 1)>0F), остальные биты F' нулевые
                ;   IX восстановлен, IYH сохраняет результат реально достигнутых детей, IYL=W[(Offset1+64) AND FF]
                ;   Coefficient0..2 содержат результат построителя, Base0..2 содержат три произведения с одним входным V
                ;   SP=входной SP+2, I, IM, IFF и paging сохраняются, порты не используются
                ;   Offset0..2 получают OffsetPhase0, wrap8(OffsetPhase1+80) и OffsetPhase2
                ;   OffsetScaleLow получает wrap8(старое+1), если этот кандидат ниже Phase2OrTarget, иначе сохраняется прежний байт
                ;   OffsetScaleHigh обнулён при ClassCode<10 и StateCode не равном 13, иначе сохранён
                ;   на активной ветви R учитывает 30+Hold+4*Small+2*Small*Different M1 подготовки плюс полный вычислитель, старший бит R сохраняется
                ;   на всех путях SP=входной SP+2, IX, I/IM/IFF и paging сохраняются, OUT отсутствует
                ;   R включает собственный префикс, достигнутые дочерние процедуры и ровно один общий вычислитель, точный R внутренней и отсечённой линии доказан для фиксированного пакета B2,00,05,00
                ;   в проверенных профилях дополнительная временная глубина достигает 28 байтов в экранном пути, общий вычислитель после возврата детей использует шесть байтов
                ; Corrupt:
                ;   HL, DE, BC, AF, HL', DE', BC', AF', IY, R, PhaseMoveTimer, условно StateCode и эффекты реально достигнутых детей, три фазовых операнда, Coefficient0..2, Base0..2, условно масштабы и CPU-стек по достигнутому пути
                ; Note:
                ;   TimedResumeCode читается как полный код состояния только на пути истечения, допустимость значения здесь не проверяется
                ;   Unknown11 является порогом младшего случайного байта в этом состоянии, общего назначения поля для всех классов не утверждается
                ;   65536 сценариев проверили все пары таймера и порога, истечение, оборачивание нуля, отказ контекста, реальное создание и экранный вывод
                ;   сверены регистры кроме R растеризатора, восемь банков и кратность записей, на путях без растеризатора R проверен точно
                ;   прежняя серия заканчивается перед F0F8, отдельная новая серия 65536 случаев исполняет весь путь до внешнего RET
                ;   новая серия имеет 65536 сценариев с точным R, включая 6547 внутренних и 3400 отсечённых линий фиксированного пакета, остальные регистры кроме T, восемь банков и кратность присваиваний совпали
                ;   проверены 10285 созданий, 4708 отказов выделения, 9947 возвратов экранного пути и 256 истечений, все дополнительные фазы и масштабы связаны с профилем
                ;   общий масштаб сохранён 40960 раз, увеличен 24576 раз, маркерный F0F8 эта серия не достигает
                ;   произвольные индексы связи, полное произведение полей, R произвольных потоков и T растеризатора, IRQ, сборка и нативная игра не доказаны
                ;   эффективное слово V перед 6D06 содержит прежний OffsetScaleLow в E и итоговый OffsetScaleHigh в D, это не входное DE всей процедуры
                ;   Hold=1 при сохранении прежнего младшего масштаба, иначе 0, Small=1 при ClassCode<10, Different=1 при StateCode не равном 13, иначе соответствующий признак нулевой
                ;   10, 13 и 80 в условиях полей обозначают шестнадцатеричные коды, числа M1 десятичные
                ;   c2 обозначает третий байтовый коэффициент, m=abs(s8(c2)) AND 7F, P=m*abs(V), Q=floor(P/128), U=P SHR 15, S=c2 XOR HIGH слова V
                ;   нулевой фактор для коэффициента 80 сохранён, знак определяется исходным байтом коэффициента и старшим байтом V
                ;   каждое Base равно -floor((abs(s8(c_i)) AND 7F)*abs(V)/128) при бите 7 c_i XOR HIGH V, иначе положительному частному, всё по модулю 65536
                ;   шесть временных байтов после возврата содержат исходный IX по SP-2, слово V по SP-4 и внутренний возврат 6D0C по SP-6, POP не очищает RAM
                ;   для фактора m>0 умножение даёт 35+floor(log2(m))+2*popcount(m) M1, при m=0 даёт 32 M1
                ;   к каждому умножению добавляются семь M1 при V<0, две при бите 7 коэффициента и четыре при бите 7 его XOR HIGH V
                ; -----------------------------------------
                ; Обновление таймера по модулю 256, истечение наступает только при исходной единице.
Entry:          LD A, (IX + @FActionRecord.PhaseMoveTimer)
                DEC A
                LD (IX + @FActionRecord.PhaseMoveTimer), A
                JR NZ, @Action.StepTimedLinkedOverlay.CheckLinked               ; переход, если уменьшенный таймер ненулевой, проверить связанную запись

                ; Восстановление полного StateCode из TimedResumeCode без добавления проверки диапазона.
                LD A, (IX + @FActionRecord.TimedResumeCode)
                LD (IX + @FActionRecord.StateCode), A
                JP @Action.PrepareObjectOffsetTransform.Entry

                ; Подготовка указателя выбранной записи и трёх кэшированных компонент текущего IX.
CheckLinked:    CALL @Action.PrepareLinkedRecordContext.Entry
                JP Z, @Action.PrepareObjectOffsetTransform.Entry                ; переход, если подготовленный контекст недоступен, продолжить общий расчёт смещений

                ; Обновление потока 0 только при доступной связанной записи.
                CALL @Action.NextRandomWord0.Entry
                ; Проверка младшего случайного байта относительно полного Unknown11 для выбора общего пути.
                LD A, L
                CP (IX + @FActionRecord.Unknown11)
                JP NC, @Action.CheckMissileSpawnWindow.Entry                    ; переход, если L не меньше Unknown11, проверить общее окно создания класса 17

                ; Обновление связанного сегмента, Carry экранного помощника в этом состоянии не изменяет продолжение.
                CALL @Action.CheckAndToggleLinkedOverlay.Entry
                JP @Action.PrepareObjectOffsetTransform.Entry

                endmodule
                endmodule
